<div class="erp-page-head"><form class="erp-filter" method="get"><input class="form-control form-control-sm" name="q" value="<?= e($_GET['q'] ?? '') ?>" placeholder="Nama/kode/telepon/NIK"><button class="btn btn-sm btn-outline-secondary">Cari</button></form>
    <?php if (can('sales.customer.create')): ?><a class="btn btn-sm btn-primary" href="<?= site_url('sales/customers/create') ?>" data-testid="customer-create-btn"><i class="bi bi-plus-lg me-1"></i>Pelanggan Baru</a><?php endif; ?></div>
<div class="card erp-card"><table class="table table-sm table-hover erp-table mb-0" data-testid="customer-table"><thead><tr><th>Kode</th><th>Nama</th><th>Tipe</th><th>Telepon</th><th>Email</th><th>Status</th></tr></thead><tbody>
<?php foreach ($page->items as $c): ?><tr data-testid="customer-row-<?= $c['id'] ?>"><td class="font-monospace small"><?= e($c['code']) ?></td><td><?php if (can('sales.customer.edit')): ?><a href="<?= site_url('sales/customers/' . $c['id'] . '/edit') ?>"><?= e($c['name']) ?></a><?php else: echo e($c['name']); endif; ?></td><td class="small"><?= e($c['customer_type']) ?></td><td class="small"><?= e($c['phone']) ?></td><td class="small"><?= e($c['email']) ?></td><td><?= status_badge($c['is_active'] ? 'ACTIVE' : 'INACTIVE') ?></td></tr><?php endforeach; ?>
